INSERT INTO master_facility_types (id, pos_code, facility_name, description, active) VALUES
(UUID(), '01', 'Pharmacy', 'A facility or location where drugs and other medically related items and services are sold, dispensed, or otherwise provided directly to patients.', 1),
(UUID(), '02', 'Unassigned', 'Unassigned', 0),
(UUID(), '03', 'School', 'A facility whose primary purpose is education.', 1),
(UUID(), '04', 'Homeless Shelter', 'A facility or location whose primary purpose is to provide temporary housing to homeless individuals (e.g., emergency shelters, individual or family shelters).', 1),
(UUID(), '05', 'Indian Health Service Free-standing Facility', 'A facility or location, owned and operated by the Indian Health Service, which provides diagnostic, therapeutic (surgical and non-surgical), and rehabilitation services to American Indians and Alaska Natives who do not require hospitalization.', 1),
(UUID(), '06', 'Indian Health Service Provider-based Facility', 'A facility or location, owned and operated by the Indian Health Service, which provides diagnostic, therapeutic (surgical and non-surgical), and rehabilitation services rendered by, or under the supervision of, physicians to American Indians and Alaska Natives admitted as inpatients or outpatients.', 1),
(UUID(), '07', 'Tribal 638 Free-standing Facility', 'A facility or location owned and operated by a federally recognized American Indian or Alaska Native tribe or tribal organization under a 638 agreement, which provides diagnostic, therapeutic (surgical and non-surgical), and rehabilitation services to tribal members who do not require hospitalization.', 1),
(UUID(), '08', 'Tribal 638 Provider-based Facility', 'A facility or location owned and operated by a federally recognized American Indian or Alaska Native tribe or tribal organization under a 638 agreement, which provides diagnostic, therapeutic (surgical and non-surgical), and rehabilitation services to tribal members admitted as inpatients or outpatients.', 1),
(UUID(), '09', 'Prison/Correctional Facility', 'A prison, jail, reformatory, work farm, detention center, or any other similar facility maintained by either Federal, State or local authorities for the purpose of confinement or rehabilitation of adult or juvenile criminal offenders.', 1),
(UUID(), '11', 'Office', 'Location, other than a hospital, skilled nursing facility (SNF), military treatment facility, community health center, State or local public health clinic, or intermediate care facility (ICF), where the health professional routinely provides health examinations, diagnosis, and treatment of illness or injury on an ambulatory basis.', 1),
(UUID(), '12', 'Home', 'Location, other than a hospital or other facility, where the patient receives care in a private residence.', 1),
(UUID(), '13', 'Assisted Living Facility', 'Congregate residential facility with self-contained living units for the accommodation of elderly and/or disabled persons that provides supportive services such as meals, housekeeping, transportation, personal care, and medication management.', 1),
(UUID(), '14', 'Group Home', 'A residence, with shared living areas, where clients receive supervision and other services such as social and/or behavioral services, custodial care, and other services that are not included in a definition of a SNF, ICF, or psychiatric facility.', 1),
(UUID(), '15', 'Mobile Unit', 'A facility/unit that moves from place-to-place equipped to provide preventive, screening, diagnostic, and/or treatment services.', 1),
(UUID(), '16', 'Temporary Lodging', 'A short-term accommodation such as a hotel, campground, hostel, cruise ship or resort where the patient receives care, and which is not identified by any other POS code.', 1),
(UUID(), '17', 'Walk-in Retail Health Clinic', 'A walk-in health clinic, other than an office, urgent care facility, pharmacy or independent clinic and not described by any other Place of Service code, that is located within a retail operation and provides, on an ambulatory basis, preventive and primary care services.', 1),
(UUID(), '18', 'Place of Employment - Worksite', 'A location, not described by any other POS code, owned or operated by a public or private entity where the patient is employed, and where a health professional provides on-going or episodic occupational medical, therapeutic or rehabilitative services to the individual.', 1),
(UUID(), '19', 'Off Campus-Outpatient Hospital', 'A portion of an off-campus hospital provider-based department which provides diagnostic, therapeutic (both surgical and non-surgical), and rehabilitation services to sick or injured persons who do not require hospitalization or institutionalization.', 1),
(UUID(), '20', 'Urgent Care Facility', 'Location, distinct from a hospital emergency room, an office, or a clinic, whose purpose is to diagnose and treat illness or injury for unscheduled, ambulatory patients seeking immediate medical attention.', 1),
(UUID(), '21', 'Inpatient Hospital', 'A facility, other than psychiatric, which primarily provides diagnostic, therapeutic (both surgical and non-surgical), and rehabilitation services by, or under, the supervision of physicians to patients admitted for a variety of medical conditions.', 1),
(UUID(), '22', 'On Campus-Outpatient Hospital', 'A portion of a hospital\'s main campus which provides diagnostic, therapeutic (both surgical and non-surgical), and rehabilitation services to sick or injured persons who do not require hospitalization or institutionalization.', 1),
(UUID(), '23', 'Emergency Room - Hospital', 'A portion of a hospital where emergency diagnosis and treatment of illness or injury is provided.', 1),
(UUID(), '24', 'Ambulatory Surgical Center', 'A freestanding facility, other than a physician\'s office, where surgical and diagnostic services are provided on an ambulatory basis.', 1),
(UUID(), '25', 'Birthing Center', 'A facility, other than a hospital\'s maternity facilities or a physician\'s office, that provides a setting for labor, delivery, and immediate post-partum care as well as immediate care of new born infants during a normal (uncomplicated) childbirth, as defined in the guidelines established by the American College of Obstetricians and Gynecologists (ACOG) or the American Academy of Pediatrics (AAP).', 1),
(UUID(), '26', 'Military Treatment Facility', 'A medical facility operated by one or more of the Uniformed Services. Military Treatment Facility (MTF) also refers to certain former U.S. Public Health Service (USPHS) facilities now designated as Uniformed Service Treatment Facilities (USTF).', 1),
(UUID(), '31', 'Skilled Nursing Facility', 'A facility which primarily provides inpatient skilled nursing care and related services to patients who require medical, nursing, or rehabilitative services but does not provide the level of care or treatment available in a hospital.', 1),
(UUID(), '32', 'Nursing Facility', 'A facility which primarily provides to residents skilled nursing care and related services for the rehabilitation of injured, disabled, or sick persons, or, on a regular basis, health-related care services above the level of custodial care to other than mentally retarded individuals.', 1),
(UUID(), '33', 'Custodial Care Facility', 'A facility that provides room, board and other personal assistance services, generally on a long-term basis, and which does not include a medical component.', 1),
(UUID(), '34', 'Hospice', 'A facility, other than a patient\'s home, in which palliative and supportive care for terminally ill patients and their families are provided.', 1),
(UUID(), '41', 'Ambulance - Land', 'A land vehicle specifically designed, equipped and staffed for lifesaving and transporting the sick or injured.', 1),
(UUID(), '42', 'Ambulance - Air or Water', 'An air or water vehicle specifically designed, equipped and staffed for lifesaving and transporting the sick or injured.', 1),
(UUID(), '49', 'Independent Clinic', 'A location, not part of a hospital and not described by any other POS code, that is organized and operated to provide preventive, diagnostic, therapeutic, rehabilitative, or palliative care services outpatients only.', 1),
(UUID(), '50', 'Federally Qualified Health Center', 'A facility located in a medically underserved area that provides Medicare beneficiaries preventive primary medical care under the general direction of a physician.', 1),
(UUID(), '51', 'Inpatient Psychiatric Facility', 'A facility that provides inpatient psychiatric services for the diagnosis and treatment of mental illness on a 24-hour basis, by or under the supervision of a physician.', 1),
(UUID(), '52', 'Psychiatric Facility - Partial Hospitalization', 'A facility for the diagnosis and treatment of mental illness that provides a planned therapeutic program of active treatment in a partial hospitalization setting, including services such as occupational therapy, individual and group therapy, patient training and activities, and family therapy.', 1),
(UUID(), '53', 'Community Mental Health Center', 'A facility that provides the following services: outpatient services, including specialized outpatient services for children, the elderly, individuals who are chronically mentally ill, and residents of its mental health service area who have been discharged from inpatient treatment at a mental health facility.', 1),
(UUID(), '54', 'Intermediate Care Facility/Individuals with Intellectual Disabilities', 'A facility which primarily provides health-related care and services above the level of custodial care to mentally retarded individuals or persons with related conditions.', 1),
(UUID(), '55', 'Residential Substance Abuse Treatment Facility', 'A facility which provides treatment for substance (alcohol and drug) abuse to live-in residents who do not require acute medical care. Services include individual and group therapy and counseling, family counseling, laboratory tests, drugs and supplies, psychological testing, and room and board.', 1),
(UUID(), '56', 'Psychiatric Residential Treatment Center', 'A facility or distinct part of a facility for psychiatric care which provides a total 24-hour therapeutically planned and professionally staffed group living and learning environment.', 1),
(UUID(), '57', 'Non-residential Substance Abuse Treatment Facility', 'A location which provides treatment for substance (alcohol and drug) abuse on an ambulatory basis. Services include individual and group therapy and counseling, family counseling, laboratory tests, drugs and supplies, and psychological testing.', 1),
(UUID(), '60', 'Mass Immunization Center', 'A location where providers administer pneumococcal pneumonia and influenza virus vaccinations and submit these services as electronic media claims, paper claims, or using the roster billing method. This generally includes a mass immunization center, a mobile unit, or any other location designated by the Centers for Medicare and Medicaid Services (CMS) as a mass immunization center.', 1),
(UUID(), '61', 'Comprehensive Inpatient Rehabilitation Facility', 'A facility that provides comprehensive rehabilitation services under the supervision of a physician to inpatients with physical disabilities. Services include physical therapy, occupational therapy, speech pathology, social or psychological services, and orthotics and prosthetics services.', 1),
(UUID(), '62', 'Comprehensive Outpatient Rehabilitation Facility', 'A facility that provides comprehensive rehabilitation services under the supervision of a physician to outpatients with physical disabilities. Services include physical therapy, occupational therapy, speech pathology, social or psychological services, and orthotics and prosthetics services.', 1),
(UUID(), '65', 'End-Stage Renal Disease Treatment Facility', 'A facility other than a hospital, which provides dialysis treatment, maintenance, and/or training to patients or caregivers on an ambulatory or home-care basis.', 1),
(UUID(), '71', 'Public Health Clinic', 'A facility maintained by either State or local health departments that provides ambulatory primary medical care under the general direction of a physician.', 1),
(UUID(), '72', 'Rural Health Clinic', 'A certified facility which is located in a rural medically underserved area that provides ambulatory primary medical care under the general direction of a physician.', 1),
(UUID(), '81', 'Independent Laboratory', 'A laboratory certified to perform diagnostic and/or clinical tests independent of an institution or a physician\'s office.', 1),
(UUID(), '99', 'Other Place of Service', 'Other place of service not identified above.', 1);
